import { mesh } from "../render";

/** register the built-in cube */
export function initMeshes(): void {
    // 24 vertices (4 per face) for per-face normals + flat shading. Each face
    // lays uv (0,0)/(1,0)/(1,1)/(0,1) over its BL→BR→TR→TL ring. Packed as
    // (posX posY posZ uvX) (normalX normalY normalZ uvY)
    // prettier-ignore
    const vertices = new Float32Array([
        // +Z
        -0.5, -0.5, 0.5, 0, 0, 0, 1, 0, 0.5, -0.5, 0.5, 1, 0, 0, 1, 0, 0.5, 0.5, 0.5, 1, 0, 0, 1, 1,
        -0.5, 0.5, 0.5, 0, 0, 0, 1, 1,
        // -Z
        0.5, -0.5, -0.5, 0, 0, 0, -1, 0, -0.5, -0.5, -0.5, 1, 0, 0, -1, 0, -0.5, 0.5, -0.5, 1, 0, 0,
        -1, 1, 0.5, 0.5, -0.5, 0, 0, 0, -1, 1,
        // +Y
        -0.5, 0.5, 0.5, 0, 0, 1, 0, 0, 0.5, 0.5, 0.5, 1, 0, 1, 0, 0, 0.5, 0.5, -0.5, 1, 0, 1, 0, 1,
        -0.5, 0.5, -0.5, 0, 0, 1, 0, 1,
        // -Y
        -0.5, -0.5, -0.5, 0, 0, -1, 0, 0, 0.5, -0.5, -0.5, 1, 0, -1, 0, 0, 0.5, -0.5, 0.5, 1, 0, -1,
        0, 1, -0.5, -0.5, 0.5, 0, 0, -1, 0, 1,
        // +X
        0.5, -0.5, 0.5, 0, 1, 0, 0, 0, 0.5, -0.5, -0.5, 1, 1, 0, 0, 0, 0.5, 0.5, -0.5, 1, 1, 0, 0,
        1, 0.5, 0.5, 0.5, 0, 1, 0, 0, 1,
        // -X
        -0.5, -0.5, -0.5, 0, -1, 0, 0, 0, -0.5, -0.5, 0.5, 1, -1, 0, 0, 0, -0.5, 0.5, 0.5, 1, -1, 0,
        0, 1, -0.5, 0.5, -0.5, 0, -1, 0, 0, 1,
    ]);

    // prettier-ignore
    const indices = new Uint32Array([
        0, 1, 2, 0, 2, 3, 4, 5, 6, 4, 6, 7, 8, 9, 10, 8, 10, 11, 12, 13, 14, 12, 14, 15, 16, 17, 18,
        16, 18, 19, 20, 21, 22, 20, 22, 23,
    ]);

    mesh({ name: "cube", vertices, indices });
}
