// Sear's sun-shadow feature, the CPU/ECS half: the off-screen light camera + its placement math.
// Shadows are sear-internal and data-gated on the `Shadow` component — like the `Tag` marker, presence
// on the directional light turns them on (and tunes them), absence is the zero-cost off path. The
// renderer (sear/index.ts) owns the GPU half — the shadow map, its render through sear's depth
// pipelines, and the group-1 binding sear's FS samples inline. This file owns only what's CPU-shaped:
// the light camera entity, where to aim + size it each frame, and the `Shadow` tuning component.
//
// The light's view is a real **off-screen ortho Camera entity** — no canvas (`attachView`), so it takes
// a cull slot and packs its viewProj through render's own `computeViewProj` like any camera. That means
// the Part pack culls casters into it as one more view, and any producer's draws bind it — no
// shadow-side view math, no producer-side caster code. The camera is created lazily on the first frame
// a casting light exists, so a scene with no `Shadow` never allocates it (matching `Tag`).
//
// Bevy's shape: the directional light owns a shadow map in the view's lighting bindings, light-data-
// gated, sampled inline — no separate shadow pass module, no coordination singleton.

import { aim, f32, type State, sparse, u32 } from "../../engine";
import { Camera, CameraMode, DirectionalLight } from "../render";
import { attachView, detachCanvas, Views } from "../render/core";
import { composeTransform, Transform } from "../transforms";

/**
 * directional sun-shadow tuning, on the {@link DirectionalLight} entity. Sear casts sun shadows for any
 * directional light carrying this component — presence is the switch (like {@link Tag} on a camera),
 * the fields are the tuning. `distance` is a **perspective** camera's coverage radius (the box
 * half-extent, centered that far ahead) — an orthographic camera auto-fits its visible ground footprint
 * and treats `distance` as a floor. `normalBias` is the primary acne fix: the receiver is shifted along
 * its surface normal by `normalBias` shadow-map texels (in world size) before the depth compare, so
 * grazing faces — where acne is worst — get more offset (raise it if acne shows, lower it if shadows
 * detach from contact edges). `depthBias` is a small residual light-clip-space depth lift the normal
 * offset can't cover (flat faces dead-on to the light). `resolution` is the shadow map's texel size.
 *
 * @example
 * ```
 * <a directional-light="direction: -0.3 -0.8 -0.55" shadow="distance: 80" />
 * ```
 */
export const Shadow = {
    distance: sparse(f32),
    depthBias: sparse(f32),
    normalBias: sparse(f32),
    resolution: sparse(u32),
};

/** the {@link Shadow} field defaults — applied on add, overridden per-attribute. `normalBias` matches
 * Bevy's directional default (1.8); `depthBias` is a small residual now the normal offset carries acne */
export const SHADOW_DEFAULTS = {
    distance: 50,
    depthBias: 0.0005,
    normalBias: 1.8,
    resolution: 2048,
};

/** the light camera's per-frame placement the renderer needs to render + bind the map: the off-screen
 * camera entity, its map resolution, the bias knobs, and the ortho half-extent `cover` (the renderer
 * derives one texel's world size — `2*cover/resolution` — for the normal offset). `null` when no casting
 * light is positioned */
export interface ShadowFrame {
    eid: number;
    size: number;
    depthBias: number;
    normalBias: number;
    cover: number;
}

// the off-screen light Camera entity, created lazily the first frame a casting light exists
let _camEid = -1;
const _camWorld = new Float32Array(16);

/**
 * the snapped light-camera placement for a directional shadow: where to put the light's eye, what it
 * looks at, and the box half-extent (`cover`) that becomes the shadow camera's ortho size. The eye is
 * snapped onto the light's texel grid (the plane perpendicular to the sun) so the shadow doesn't crawl
 * as the camera moves. Reads only the camera's pose + size — never its projection — so a negative near
 * clip is handled with no special case. Pure; exported for the placement test.
 *
 * An **orthographic** camera's shadow fits the visible ground (y=0) footprint: its four screen-corner
 * rays meet the ground at four points, and the box centers on their centroid and spans their bounding
 * radius. That footprint is derived from the camera's size + aspect + pitch (the ray tilt), so coverage
 * tracks zoom and never cuts off into a square — and it's centered where the camera actually looks, not
 * a fixed distance ahead. A **perspective** camera uses `distance` as the coverage radius and looks
 * that far ahead. `distance` is the world coverage floor either way (raise it to widen the minimum).
 */
export function shadowPlacement(
    camWorld: Float32Array,
    mode: number,
    camSize: number,
    aspect: number,
    dir: readonly [number, number, number],
    distance: number,
    resolution: number,
): {
    eye: [number, number, number];
    focus: [number, number, number];
    up: [number, number, number];
    cover: number;
} {
    const px = camWorld[12];
    const py = camWorld[13];
    const pz = camWorld[14];
    // camera looks down its local -Z; the world matrix's Z column is +Z, so forward is its negation
    let fx = -camWorld[8];
    let fy = -camWorld[9];
    let fz = -camWorld[10];
    const fl = Math.hypot(fx, fy, fz) || 1;
    fx /= fl;
    fy /= fl;
    fz /= fl;

    let cenX: number;
    let cenY: number;
    let cenZ: number;
    let cover: number;
    if (mode === CameraMode.Orthographic && fy < -1e-3) {
        // camera right + up world axes (matrix columns 0, 1), normalized
        let crx = camWorld[0];
        let cry = camWorld[1];
        let crz = camWorld[2];
        const crl = Math.hypot(crx, cry, crz) || 1;
        crx /= crl;
        cry /= crl;
        crz /= crl;
        let cux = camWorld[4];
        let cuy = camWorld[5];
        let cuz = camWorld[6];
        const cul = Math.hypot(cux, cuy, cuz) || 1;
        cux /= cul;
        cuy /= cul;
        cuz /= cul;

        // the center ray meets the ground (y=0) at the look point. A screen-corner offset `v` slides its
        // parallel ray's ground hit by `v - (v.y / forward.y) * forward` (extra travel as v changes the
        // y it must fall). So the footprint corners are centroid ± Dr ± Du for the half-width/height
        // offsets — Dr, Du lie in the ground plane, and the bounding radius is the longer half-diagonal.
        const t0 = -py / fy;
        cenX = px + t0 * fx;
        cenY = 0;
        cenZ = pz + t0 * fz;
        const hw = camSize * aspect;
        const hh = camSize;
        const krx = hw * (crx - (cry / fy) * fx);
        const krz = hw * (crz - (cry / fy) * fz);
        const kux = hh * (cux - (cuy / fy) * fx);
        const kuz = hh * (cuz - (cuy / fy) * fz);
        const diagA = Math.hypot(krx + kux, krz + kuz);
        const diagB = Math.hypot(krx - kux, krz - kuz);
        cover = Math.max(diagA, diagB);
    } else {
        cenX = px + fx * distance;
        cenY = py + fy * distance;
        cenZ = pz + fz * distance;
        cover = distance;
    }

    let dx = dir[0];
    let dy = dir[1];
    let dz = dir[2];
    const dl = Math.hypot(dx, dy, dz) || 1;
    dx /= dl;
    dy /= dl;
    dz /= dl;

    // an orthonormal basis in the plane perpendicular to the sun, to snap the eye onto. up0 avoids the
    // degenerate parallel case when the sun points near-straight-down
    const upY = Math.abs(dy) > 0.99 ? 0 : 1;
    const upZ = Math.abs(dy) > 0.99 ? 1 : 0;
    let rx = upY * dz - upZ * dy;
    let ry = upZ * dx;
    let rz = -upY * dx;
    const rl = Math.hypot(rx, ry, rz) || 1;
    rx /= rl;
    ry /= rl;
    rz /= rl;
    const ux = dy * rz - dz * ry;
    const uy = dz * rx - dx * rz;
    const uz = dx * ry - dy * rx;

    let ex = cenX - dx * cover;
    let ey = cenY - dy * cover;
    let ez = cenZ - dz * cover;

    const texel = (2 * cover) / resolution;
    const er = ex * rx + ey * ry + ez * rz;
    const eu = ex * ux + ey * uy + ez * uz;
    const sr = Math.round(er / texel) * texel - er;
    const su = Math.round(eu / texel) * texel - eu;
    ex += sr * rx + su * ux;
    ey += sr * ry + su * uy;
    ez += sr * rz + su * uz;

    return {
        eye: [ex, ey, ez],
        focus: [ex + dx * cover, ey + dy * cover, ez + dz * cover],
        up: [0, upY, upZ],
        cover,
    };
}

// create the off-screen light Camera entity: an ortho camera with no canvas (`attachView`), so it takes
// a cull slot but draws no framebuffer. Lazy — only the first frame a casting light needs it
function createCamera(state: State): void {
    const eid = state.create();
    state.add(eid, Transform);
    state.add(eid, Camera);
    Camera.mode.set(eid, CameraMode.Orthographic);
    Camera.near.set(eid, 0);
    Camera.far.set(eid, 2);
    Camera.size.set(eid, 1);
    attachView(eid);
    _camEid = eid;
}

/** destroy the light camera + its view (at plugin dispose). The camera lives in a State, not on the
 * device, so the renderer's GPU teardown is separate ({@link disposeSear}) */
export function destroyShadowCamera(state: State): void {
    if (_camEid < 0) return;
    detachCanvas(_camEid);
    state.destroy(_camEid);
    _camEid = -1;
}

/**
 * aim + size the light camera from the casting sun + the `main` Sear camera, so `BeginFrameSystem` packs
 * its viewProj this frame. Runs in the `simulation` group, before the draw frame opens. Returns `null`
 * — and casts nothing — when no directional light carries a {@link Shadow}, or there's no main camera to
 * center on; the renderer falls back to fully lit. Creates the off-screen camera lazily the first frame
 * a casting light exists, so the bare path (no `Shadow`) allocates neither camera nor map.
 */
export function updateShadowCamera(state: State, main: number): ShadowFrame | null {
    const light = state.only([DirectionalLight]);
    if (light < 0 || !state.has(light, Shadow) || main < 0) return null;
    // spawning the off-screen camera is an entity add, which the always-mode contract forbids in edit
    // mode — so it lands lazily on the first play frame a caster exists, never while editing
    if (_camEid < 0) {
        if (state.mode === "edit") return null;
        createCamera(state);
    }

    const distance = Math.max(1e-3, Shadow.distance.get(light));
    const depthBias = Shadow.depthBias.get(light);
    const normalBias = Shadow.normalBias.get(light);
    const size = Math.max(1, Shadow.resolution.get(light) | 0);
    const dir: [number, number, number] = [
        DirectionalLight.direction.x.get(light),
        DirectionalLight.direction.y.get(light),
        DirectionalLight.direction.z.get(light),
    ];
    // an ortho camera's footprint depends on its view size + aspect, so the shadow tracks zoom
    const view = Views.get(main);
    const aspect = view && view.height > 0 ? view.width / view.height : 1;
    composeTransform(main, _camWorld);
    const p = shadowPlacement(
        _camWorld,
        Camera.mode.get(main),
        Camera.size.get(main),
        aspect,
        dir,
        distance,
        size,
    );
    const q = aim(
        p.eye[0],
        p.eye[1],
        p.eye[2],
        p.focus[0],
        p.focus[1],
        p.focus[2],
        p.up[0],
        p.up[1],
        p.up[2],
    );
    Transform.pos.set(_camEid, p.eye[0], p.eye[1], p.eye[2], 1);
    Transform.rot.set(_camEid, q.x, q.y, q.z, q.w);
    Camera.mode.set(_camEid, CameraMode.Orthographic);
    Camera.size.set(_camEid, p.cover);
    Camera.near.set(_camEid, 0);
    Camera.far.set(_camEid, 2 * p.cover);
    return { eid: _camEid, size, depthBias, normalBias, cover: p.cover };
}
